using System;using System.Linq;using System.Collections.Generic;using AirBridge.UI;
class LayoutTest{
 static AudioNode N(string id,bool input,bool module=false){return new AudioNode{Id=id,Input=input,Module=module};}static AudioLink E(string s,string t){return new AudioLink{Source=s,Target=t};}static void Check(bool b,string m){if(!b)throw new Exception(m);}
 static int Cross(NodePosition[] p,AudioLink[] e){var d=p.ToDictionary(x=>x.Id);int count=0;for(int i=0;i<e.Length;i++)for(int j=i+1;j<e.Length;j++)if((d[e[i].Source].Y-d[e[j].Source].Y)*(d[e[i].Target].Y-d[e[j].Target].Y)<0)count++;return count;}
 static void Main(){var n=new[]{N("pc",true),N("iphone",true),N("android",true),N("pot",true),N("edge",true),N("default",false),N("speaker",false)};var e=new[]{E("pc","default"),E("iphone","default"),E("android","default"),E("pot","speaker"),E("edge","default")};var p=BoardLayout.Arrange(n,e);Check(Cross(p,e)==0,"Screenshot crossing remains");Check(p.Length==n.Length&&e.Length==5,"Graph lost elements");var again=BoardLayout.Arrange(n,e);Check(p.Zip(again,(a,b)=>a.Id==b.Id&&a.X==b.X&&a.Y==b.Y).All(x=>x),"Unstable layout");var chain=new[]{N("phone",true),N("eq",false,true),N("gain",false,true),N("out",false)};var c=BoardLayout.Arrange(chain,new[]{E("phone","eq"),E("eq","gain"),E("gain","out")}).ToDictionary(x=>x.Id);Check(c["phone"].X<c["eq"].X&&c["eq"].X<c["gain"].X&&c["gain"].X<c["out"].X,"Effect layers overlap");Check(BoardLayout.Arrange(new AudioNode[0],new AudioLink[0]).Length==0,"Empty graph");Check(BoardLayout.Arrange(chain,new[]{E("eq","gain"),E("gain","eq"),E("gone","out")}).Length==4,"Cycle fallback");Console.WriteLine("PASS screenshot: zero crossings; stable ordering, effect layers, empty/stale/cyclic drafts; graph unchanged.");}
}
